26: // ── Constants ─────────────────────────────────────────────────────
27: 
28: const DOCS_DIR = "aidd_docs";
29: const MEMORY_SUBDIR = "memory";
30: const ON_DEMAND_DIRS = ["internal", "external"];
31: const BLOCK_OPEN = "<aidd_project_memory>";
32: const BLOCK_CLOSE = "</aidd_project_memory>";
33: const ON_DEMAND_NOTE = "<!-- read on demand, not auto-loaded -->";
34: const EXCLUDED_FILES = new Set([".gitkeep", "README.md"]);
