36: // Human-facing index of the memory bank. The hook refreshes the list between
37: // these markers; everything else in the file is hand-written and preserved.
38: const MEMORY_README = "README.md";
39: const TOC_OPEN = "<!-- files:start -->";
40: const TOC_CLOSE = "<!-- files:end -->";
41: 
42: const TARGET_FILES = [
43:   { path: "CLAUDE.md", syntax: "at" },
44:   { path: "AGENTS.md", syntax: "at" },
45:   { path: ".github/copilot-instructions.md", syntax: "link" },
46: ];
