48: // Which context file each tool reads. Mirrors the skill's references/tools.md.
49: const TOOL_FILES = {
50:   claude: "CLAUDE.md",
51:   codex: "AGENTS.md",
52:   cursor: "AGENTS.md",
53:   opencode: "AGENTS.md",
54:   copilot: ".github/copilot-instructions.md",
55: };
