57: // ── Helpers ───────────────────────────────────────────────────────
58: 
59: function memoryPath(path, ...parts) {
60:   return path.join(DOCS_DIR, MEMORY_SUBDIR, ...parts);
61: }
62: 
63: // Read a file's text, or null if it does not exist. Opening directly (instead
64: // of an existsSync check first) avoids a time-of-check/time-of-use race: the
65: // file is touched exactly once. Real errors (permissions, etc.) still throw.
66: function readTextOrNull(fs, filePath) {
67:   try {
68:     return fs.readFileSync(filePath, "utf8");
69:   } catch (err) {
70:     if (err.code === "ENOENT") return null;
71:     throw err;
72:   }
73: }
74: 
75: // List a directory, or [] if it does not exist. Same single-touch rationale as
76: // readTextOrNull: no separate existence check before reading.
77: function readDirOrEmpty(fs, dir) {
78:   try {
79:     return fs.readdirSync(dir, { withFileTypes: true });
80:   } catch (err) {
81:     if (err.code === "ENOENT") return [];
82:     throw err;
83:   }
84: }
