86: // Top-level .md at the root of memory/ (always-loaded tier).
87: function scanRootFiles(fs, path) {
88:   return readDirOrEmpty(fs, memoryPath(path))
89:     .filter((e) => e.isFile() && e.name.endsWith(".md") && !EXCLUDED_FILES.has(e.name))
90:     .map((e) => memoryPath(path, e.name))
91:     .sort();
92: }
93: 
94: // .md under memory/<sub>/ recursively (on-demand tier).
95: function scanSubdir(fs, path, sub) {
96:   const out = [];
97:   const walk = (dir) => {
98:     for (const e of readDirOrEmpty(fs, dir)) {
99:       const full = path.join(dir, e.name);
100:       if (e.isDirectory()) walk(full);
101:       else if (e.name.endsWith(".md") && !EXCLUDED_FILES.has(e.name)) out.push(full);
102:     }
103:   };
104:   walk(memoryPath(path, sub));
105:   return out.sort();
106: }
