108: function buildReference(syntax, filePath) {
109:   const rel = filePath.replace(/\\/g, "/");
110:   return syntax === "link" ? `[${rel}](../${rel})` : `@${rel}`;
111: }
112: 
113: function buildBlockContent(rootFiles, onDemandFiles, syntax) {
114:   const lines = [];
115:   for (const f of rootFiles) lines.push(buildReference(syntax, f));
116:   if (onDemandFiles.length > 0) {
117:     lines.push("", ON_DEMAND_NOTE);
118:     for (const f of onDemandFiles) lines.push(`- ${f.replace(/\\/g, "/")}`);
119:   }
120:   if (lines.length === 0) return "";
121:   return `\n${lines.join("\n")}\n`;
122: }
123: 
124: // Replace the text between an open and close marker, leaving the rest intact.
125: // Anchor on the close, then take the nearest open before it: a bare marker
126: // quoted in hand-written prose above the real block must not become the cut
127: // point and splice out everything between it and the block.
128: function updateMarkers(content, open, close, innerContent) {
129:   const closeIdx = content.indexOf(close);
130:   if (closeIdx === -1) return null;
131:   const openIdx = content.lastIndexOf(open, closeIdx);
132:   if (openIdx === -1) return null;
133:   return content.slice(0, openIdx + open.length) + innerContent + content.slice(closeIdx);
134: }
135: 
136: function updateBlock(content, innerContent) {
137:   return updateMarkers(content, BLOCK_OPEN, BLOCK_CLOSE, innerContent);
138: }
139: 
140: // memory/-relative path, e.g. aidd_docs/memory/internal/x.md -> internal/x.md.
141: function memoryRelative(path, filePath) {
142:   return filePath.replace(/\\/g, "/").replace(`${memoryPath(path)}/`, "");
143: }
