145: // Human-facing TOC of the memory bank, grouped by load tier.
146: function buildToc(rootFiles, onDemandFiles, path) {
147:   const link = (f) => {
148:     const rel = memoryRelative(path, f);
149:     return `- [${rel}](${rel})`;
150:   };
151:   const lines = rootFiles.map(link);
152:   if (onDemandFiles.length > 0) {
153:     lines.push("", "Read on demand:", "", ...onDemandFiles.map(link));
154:   }
155:   if (lines.length === 0) lines.push("_No memory files yet._");
156:   return `\n${lines.join("\n")}\n`;
157: }
