159: // The context files to fill. No tool named: every target already present, which
160: // is what the auto hook wants. Tools named: only theirs, so an AGENTS.md the
161: // user never picked keeps its block untouched.
162: function resolveTargets(tools) {
163:   if (tools.length === 0) return TARGET_FILES;
164: 
165:   const unknown = tools.filter((t) => !(t in TOOL_FILES));
166:   if (unknown.length > 0) {
167:     const known = Object.keys(TOOL_FILES).join(", ");
168:     console.error(`update_memory: unknown tool ${unknown.join(", ")} (known: ${known})`);
169:     process.exit(1);
170:   }
171: 
172:   const wanted = new Set(tools.map((t) => TOOL_FILES[t]));
173:   return TARGET_FILES.filter((target) => wanted.has(target.path));
174: }
