177:   try {
178:     childProcess.execSync(`git add ${files.map((f) => `"${f}"`).join(" ")}`, {
179:       stdio: ["pipe", "pipe", "pipe"],
180:     });
181:   } catch {
182:     // silent: no git or not a repo
183:   }
184: }
