188: (async () => {
189:   const fs = await import("node:fs");
190:   const path = await import("node:path");
191:   const childProcess = await import("node:child_process");
192: 
193:   // Every path below is project-relative, so anchor on the project root when
194:   // Claude Code names it. Without this a run started elsewhere finds no bank
195:   // and exits 0, which reads as success.
196:   const root = process.env.CLAUDE_PROJECT_DIR;
197:   if (root && fs.existsSync(root)) process.chdir(root);
